function storefrontLabel(attribute,key,fallback){
var label=document.body.getAttribute(attribute);
return label && label !==key ? label:fallback;
}
function storefrontCloseButton(dismiss){
return $('<button type="button" class="popup-close"></button>')
.attr('data-dismiss',dismiss)
.attr('aria-label',storefrontLabel('data-close-label','button_close','Close'))
.append('<img src="catalog/view/theme/charm_by_sylora/image/icons/atelier/close.svg" width="24" height="24" alt="">');
}
function createStorefrontNotice(message,tone,trigger,actions){
var alertClass=tone==='cart' ? 'success':tone;
var icon=tone==='success' || tone==='cart' ? 'check':'alert';
var close=storefrontCloseButton('alert');
var notice=$('<div class="alert alert-dismissible site-notice" role="status"></div>').addClass('alert-'+alertClass);
var content=$('<p class="site-notice__message"></p>').append(message);
if(tone==='cart'){
notice.addClass('cart-notice');
}
notice.append($('<img class="site-notice__icon" alt="" width="24" height="24">')
.attr('src','catalog/view/theme/charm_by_sylora/image/icons/atelier/'+icon+'.svg'),content,close);
if(actions){
notice.append(actions);
}
notice.one('closed.bs.alert',function(){
if(trigger && trigger.isConnected && document.activeElement===document.body){
trigger.focus({preventScroll:true});
}
});
return notice;
}
function showSiteNotification(message,tone,trigger,actions){
var host=$('#site-notifications');
if(!host.length){
host=$('<div id="site-notifications" class="site-notifications" aria-live="polite" aria-atomic="true"></div>');
$('body').prepend(host);
}
host.empty().append(createStorefrontNotice(message,tone,trigger,actions));
}
function cartNoticeActions(response){
return $('<div class="cart-notice__actions"></div>').append(
$('<a class="btn btn-primary"></a>').attr('href',response.cart_url || 'index.php?route=checkout/cart')
.text(response.text_cart_action || 'Перейти в корзину'),
$('<a class="btn btn-default"></a>').attr('href',response.continue_url || 'index.php?route=product/search')
.text(response.text_continue_action || 'Продолжить покупки')
);
}
function showProductActionError(trigger){
var message=storefrontLabel('data-popup-error','error_popup_action','The action failed. Please try again.');
showSiteNotification(document.createTextNode(message),'danger',trigger);
}
function showStorefrontModal(modal,trigger){
modal.one('shown.bs.modal',function(){
modal.find('.popup-close').first().trigger('focus');
}).one('hidden.bs.modal',function(){
modal.remove();
if(trigger && trigger.isConnected){
trigger.focus({preventScroll:true});
}
}).on('keydown',function(event){
if(event.key !=='Tab'){
return;
}
var focusable=modal.find('a[href],button,input,select,textarea,[tabindex="0"]')
.filter(':visible:not(:disabled):not([tabindex="-1"])');
var first=focusable[0];
var last=focusable[focusable.length-1];
if(event.shiftKey && document.activeElement===first){
event.preventDefault();
last.focus();
}else if(!event.shiftKey && document.activeElement===last){
event.preventDefault();
first.focus();
}
}).modal('show',trigger);
}
function setProductActionLoading(trigger,loading){
if(!trigger){
return;
}
var element=$(trigger);
if(loading){
element.data('was-disabled',element.prop('disabled'));
element.prop('disabled',true).attr('aria-busy','true').addClass('is-loading');
}else{
element.prop('disabled',Boolean(element.data('was-disabled'))).removeAttr('aria-busy').removeClass('is-loading');
}
}
function confirmProductAction(trigger,action){
if(!trigger){
return;
}
var element=$(trigger);
if(action==='wishlist'){
var tooltip=element.find('.catalog-card__tooltip');
var selectedLabel=element.attr('data-wishlist-selected-label');
if(tooltip.length && selectedLabel){
tooltip.text(selectedLabel);
element.attr('aria-label',selectedLabel);
}else{
element.attr({
'aria-label':'Товар в избранном',
'data-original-title':'В избранном',
'title':'В избранном'
});
}
element.attr('aria-pressed','true').addClass('is-selected');
}else{
element.addClass('is-confirmed');
window.setTimeout(function(){
element.removeClass('is-confirmed');
},1400);
}
}
var cart={
'add':function(product_id,quantity,trigger){
$.ajax({
url:'index.php?route=checkout/cart/add',
type:'post',
data:'product_id='+product_id+'&quantity='+(typeof(quantity)!='undefined' ? quantity:1),
dataType:'json',
beforeSend:function(){
$('#cart>button').button('loading');
setProductActionLoading(trigger,true);
},
complete:function(){
$('#cart>button').button('reset');
setProductActionLoading(trigger,false);
},
success:function(json){
$('.alert-dismissible,.text-danger').remove();
if(json['redirect']){
location=json['redirect'];
}
if(json['success']){
document.dispatchEvent(new CustomEvent('sylora:cart-add',{detail:{product_id:product_id,quantity:(typeof(quantity)!='undefined' ? quantity:1)}}));
showSiteNotification(json['success'],'cart',trigger,cartNoticeActions(json));
confirmProductAction(trigger,'cart');
setTimeout(function(){
$('#cart>button #cart-total').text(json['total']);
},100);
$('#cart>ul').load('index.php?route=common/cart/info ul li');
}
},
error:function(){
showProductActionError(trigger);
}
});
},
'update':function(key,quantity){
$.ajax({
url:'index.php?route=checkout/cart/edit',
type:'post',
data:'key='+key+'&quantity='+(typeof(quantity)!='undefined' ? quantity:1),
dataType:'json',
beforeSend:function(){
$('#cart>button').button('loading');
},
complete:function(){
$('#cart>button').button('reset');
},
success:function(json){
setTimeout(function(){
$('#cart>button #cart-total').text(json['total']);
},100);
if($('#checkout-cart').length || getURLVar('route')=='checkout/cart' || getURLVar('route')=='checkout/checkout'){
location='index.php?route=checkout/cart';
}else{
$('#cart>ul').load('index.php?route=common/cart/info ul li');
}
},
error:function(xhr,ajaxOptions,thrownError){
alert(thrownError+"\r\n"+xhr.statusText+"\r\n"+xhr.responseText);
}
});
},
'remove':function(key,product_id,quantity){
$.ajax({
url:'index.php?route=checkout/cart/remove',
type:'post',
data:'key='+key,
dataType:'json',
beforeSend:function(){
$('#cart>button').button('loading');
},
complete:function(){
$('#cart>button').button('reset');
},
success:function(json){
document.dispatchEvent(new CustomEvent('sylora:cart-remove',{detail:{key:key,product_id:product_id,quantity:quantity}}));
setTimeout(function(){
$('#cart>button #cart-total').text(json['total']);
},100);
if($('#checkout-cart').length || getURLVar('route')=='checkout/cart' || getURLVar('route')=='checkout/checkout'){
location='index.php?route=checkout/cart';
}else{
$('#cart>ul').load('index.php?route=common/cart/info ul li');
}
},
error:function(xhr,ajaxOptions,thrownError){
alert(thrownError+"\r\n"+xhr.statusText+"\r\n"+xhr.responseText);
}
});
}
}
